-- jira_issues is a disposable cache (regenerated by sync-jira-sprint-data),
-- so this rebuilds its key shape directly rather than trying to preserve
-- rows: drop the old single-column primary key on "key", then key the table
-- on "id" (`${sprintId}:${key}`) instead, since the same Jira issue can
-- legitimately appear under both the synced current and previous sprint.
TRUNCATE TABLE "jira_issues";--> statement-breakpoint
ALTER TABLE "jira_issues" DROP CONSTRAINT IF EXISTS "jira_issues_pkey";--> statement-breakpoint
ALTER TABLE "jira_issues" ADD COLUMN "id" text PRIMARY KEY NOT NULL;--> statement-breakpoint
CREATE INDEX "jira_issues_key_idx" ON "jira_issues" USING btree ("key");
